pub extern "C" fn xmlNextChar(mut ctxt: xmlParserCtxtPtr) { unsafe {
    let mut current_block: u64;
    let mut cur: *const c_uchar = ::core::ptr::null::<c_uchar>();
    let mut avail: size_t = 0;
    let mut c: c_int = 0;
    if ctxt.is_null()
        || (*ctxt).instate as c_int == XML_PARSER_EOF as c_int
        || (*ctxt).input.is_null()
    {
        return;
    }
    avail = (*(*ctxt).input).end.offset_from((*(*ctxt).input).cur) as c_long as size_t;
    if avail < INPUT_CHUNK as size_t {
        xmlParserGrow(ctxt);
        if (*ctxt).instate as c_int == XML_PARSER_EOF as c_int
            || (*(*ctxt).input).cur >= (*(*ctxt).input).end
        {
            return;
        }
        avail =
            (*(*ctxt).input).end.offset_from((*(*ctxt).input).cur) as c_long as size_t;
    }
    cur = (*(*ctxt).input).cur as *const c_uchar;
    c = *cur as c_int;
    if c < 0x80 as c_int {
        if c == '\n' as i32 {
            (*(*ctxt).input).cur = (*(*ctxt).input).cur.offset(1);
            (*(*ctxt).input).line += 1;
            (*(*ctxt).input).col = 1 as c_int;
        } else if c == '\r' as i32 {
            (*(*ctxt).input).cur = (*(*ctxt).input).cur.offset(
                (if *cur.offset(1 as c_int as isize) as c_int
                    == '\n' as i32
                {
                    2 as c_int
                } else {
                    1 as c_int
                }) as isize,
            );
            (*(*ctxt).input).line += 1;
            (*(*ctxt).input).col = 1 as c_int;
            return;
        } else {
            (*(*ctxt).input).cur = (*(*ctxt).input).cur.offset(1);
            (*(*ctxt).input).col += 1;
        }
    } else {
        (*(*ctxt).input).col += 1;
        if avail < 2 as size_t
            || *cur.offset(1 as c_int as isize) as c_int
                & 0xc0 as c_int
                != 0x80 as c_int
        {
            current_block = 10664207195514096503;
        } else if c < 0xe0 as c_int {
            if c < 0xc2 as c_int {
                current_block = 10664207195514096503;
            } else {
                (*(*ctxt).input).cur = (*(*ctxt).input)
                    .cur
                    .offset(2 as c_int as isize);
                current_block = 14434620278749266018;
            }
        } else {
            let mut val: c_uint = (c << 8 as c_int
                | *cur.offset(1 as c_int as isize) as c_int)
                as c_uint;
            if avail < 3 as size_t
                || *cur.offset(2 as c_int as isize) as c_int
                    & 0xc0 as c_int
                    != 0x80 as c_int
            {
                current_block = 10664207195514096503;
            } else if c < 0xf0 as c_int {
                if val < 0xe0a0 as c_uint
                    || val >= 0xeda0 as c_uint && val < 0xee00 as c_uint
                {
                    current_block = 10664207195514096503;
                } else {
                    (*(*ctxt).input).cur = (*(*ctxt).input)
                        .cur
                        .offset(3 as c_int as isize);
                    current_block = 14434620278749266018;
                }
            } else if avail < 4 as size_t
                || *cur.offset(3 as c_int as isize) as c_int
                    & 0xc0 as c_int
                    != 0x80 as c_int
            {
                current_block = 10664207195514096503;
            } else if val < 0xf090 as c_uint || val >= 0xf490 as c_uint {
                current_block = 10664207195514096503;
            } else {
                (*(*ctxt).input).cur = (*(*ctxt).input)
                    .cur
                    .offset(4 as c_int as isize);
                current_block = 14434620278749266018;
            }
        }
        match current_block {
            14434620278749266018 => {}
            _ => {
                if (*(*ctxt).input).flags as c_uint & XML_INPUT_ENCODING_ERROR
                    == 0 as c_uint
                {
                    if ctxt.is_null()
                        || (*ctxt).input.is_null()
                        || ((*(*ctxt).input).end.offset_from((*(*ctxt).input).cur)
                            as c_long)
                            < 4 as c_long
                    {
                        __xmlErrEncoding(
                            ctxt,
                            XML_ERR_INVALID_CHAR,
                            b"Input is not proper UTF-8, indicate encoding !\n\0" as *const u8
                                as *const c_char,
                            ::core::ptr::null::<xmlChar>(),
                            ::core::ptr::null::<xmlChar>(),
                        );
                    } else {
                        let mut buffer: [c_char; 150] = [0; 150];
                        snprintf(
                            &raw mut buffer as *mut c_char,
                            149 as size_t,
                            b"Bytes: 0x%02X 0x%02X 0x%02X 0x%02X\n\0" as *const u8
                                as *const c_char,
                            *(*(*ctxt).input)
                                .cur
                                .offset(0 as c_int as isize)
                                as c_int,
                            *(*(*ctxt).input)
                                .cur
                                .offset(1 as c_int as isize)
                                as c_int,
                            *(*(*ctxt).input)
                                .cur
                                .offset(2 as c_int as isize)
                                as c_int,
                            *(*(*ctxt).input)
                                .cur
                                .offset(3 as c_int as isize)
                                as c_int,
                        );
                        __xmlErrEncoding(
                            ctxt,
                            XML_ERR_INVALID_CHAR,
                            b"Input is not proper UTF-8, indicate encoding !\n%s\0" as *const u8
                                as *const c_char,
                            &raw mut buffer as *mut c_char as *mut xmlChar,
                            ::core::ptr::null::<xmlChar>(),
                        );
                    }
                    (*(*ctxt).input).flags = ((*(*ctxt).input).flags as c_uint
                        | XML_INPUT_ENCODING_ERROR)
                        as c_int;
                }
                (*(*ctxt).input).cur = (*(*ctxt).input).cur.offset(1);
                return;
            }
        }
    };
} }
